import random
random.seed(3)

text = ("the cat sat on the mat . the dog sat on the rug . "
        "the cat chased the dog . the dog chased the ball .").split()

# Classic ML answers a question about input: is this sentence about a cat?
def is_about_cat(sentence):
    return "cat" in sentence.split()

print("Classify:", is_about_cat("the cat sat on the rug"))

# Generative AI creates NEW content that looks like its training data.
# Here: learn which word can follow which, then chain random choices.
follows = {}
for a, b in zip(text, text[1:]):
    follows.setdefault(a, []).append(b)

for _ in range(3):
    word, sentence = "the", ["the"]
    while word != "." and len(sentence) < 12:
        word = random.choice(follows[word])
        sentence.append(word)
    print("Generate:", " ".join(sentence))

import random
from collections import Counter, defaultdict
random.seed(0)

model = defaultdict(Counter)   # word -> counts of the words that followed it

def train(text, weight=1):
    words = text.split()
    for a, b in zip(words, words[1:]):
        model[a][b] += weight

def generate(start="answer :"):
    words = start.split()
    while words[-1] != "." and model[words[-1]]:
        options = model[words[-1]]
        words.append(random.choices(list(options), list(options.values()))[0])
    return " ".join(words)

def helpful_share(n=200):
    return sum("help" in generate() for _ in range(n)) / n

# Stage 1 - pretraining: lots of ordinary internet text. Learns language, not manners.
train("answer : who knows . answer : stop asking me . answer : happy to help .")
print(f"Base model helpful:       {helpful_share():.0%}")

# Stage 2 - fine-tuning: fewer, high-quality example conversations count extra.
train("answer : happy to help .", weight=6)
print(f"Fine-tuned model helpful: {helpful_share():.0%}")

# Stage 3 - preference tuning: compare two replies, a reward model picks the
# better one, and the model is trained a little more on the winner.
def reward(reply):
    return ("help" in reply) - ("stop" in reply)

for _ in range(30):
    a, b = generate(), generate()
    train(max(a, b, key=reward))
print(f"After preference tuning:  {helpful_share():.0%}")
